<template><view class="me-page">
  <view class="me-nav" :style="{paddingTop:nav.statusBar+'px'}"><view :style="{height:nav.height+'px',paddingRight:nav.right+'px'}"><text>我的</text><button @tap="account('settings')">设置</button></view></view>
  <view class="me-body"><view class="identity" @tap="account('settings')"><view class="avatar">{{cloudSession.user?.nickname?.slice(0,1)||'豆'}}</view><view class="identity-copy"><text class="identity-title">{{cloudSession.user?.nickname||'你好，创作者'}}</text><text class="muted">{{cloudSession.user?'作品和拼豆进度已同步':'登录保存作品，换手机也能接着拼'}}</text></view><AppIcon name="chevron" :size="30"/></view>
    <button v-if="!cloudSession.user" class="primary-btn login" @tap="account()">登录 / 注册<text>保存图纸与进度</text></button>
    <view class="stats"><button @tap="works"><text>{{summary.works||0}}</text>云端作品</button><button @tap="favorites"><text>{{summary.favorites||0}}</text>我的收藏</button><button @tap="inventory"><text>{{formatStock(summary.stock)}}</text>豆盒库存</button></view>
    <view v-if="error" class="retry"><text>{{error}}</text><button @tap="load">重新连接</button></view>
    <view v-if="summary.recent" class="recent" @tap="continueWork"><view class="recent-icon"><AppIcon name="grid" :size="36"/></view><view><text class="row-title">继续上次的创作</text><text class="muted ellipsis">{{summary.recent.name}} · {{summary.recent.size}} 格</text></view><AppIcon name="arrow-right" :size="30"/></view>
    <text class="group-label">我的创作</text><view class="tool-grid"><button @tap="favorites"><view class="tool-symbol">♡</view><text>我的收藏</text><text class="muted">下次想拼的灵感</text></button><button @tap="inventory"><view class="tool-symbol"><AppIcon name="palette" :size="40"/></view><text>我的豆盒</text><text class="muted">库存与缺豆清单</text></button><button @tap="account('tools')"><view class="tool-symbol"><AppIcon name="upload" :size="40"/></view><text>导入与迁移</text><text class="muted">接着以前的作品</text></button></view>
    <button class="membership-compact" @tap="account('membership')"><view class="pro-badge">PRO</view><view><text>{{cloudSession.entitlements.isPro?'我的 Pro 权益':'打印与 Pro'}}</text><text>{{cloudSession.entitlements.isPro?'有效期至 '+formatDate(cloudSession.entitlements.proUntil):'分页打印 · 高级图纸'}} · {{cloudSession.entitlements.exportCredits||0}} 次打印可用</text></view><AppIcon name="chevron" :size="28"/></button>
    <text class="group-label">服务与支持</text><view class="menu-list"><button @tap="guide"><AppIcon name="image" :size="32"/><text>新手教程</text><text class="menu-hint">从选图到熨烫 ›</text></button><button @tap="account('orders')"><AppIcon name="folder" :size="32"/><text>我的订单</text><text class="menu-hint">{{summary.pendingOrders?summary.pendingOrders+' 笔待付款':'购买记录与权益'}}<text> ›</text></text></button><button @tap="account('support')"><AppIcon name="help" :size="32"/><text>客服与图纸定制</text><text class="menu-hint">{{summary.openTickets?summary.openTickets+' 个处理中':'有问题，找我们'}} ›</text></button><button @tap="privacy"><AppIcon name="shield" :size="32"/><text>隐私与服务说明</text><text class="menu-hint">了解云端保存 ›</text></button></view>
    <view class="me-footer"><BrandMark/><text>豆物 · 一颗颗拼出喜欢</text></view>
  </view>
</view></template>
<script setup>
import {ref,watch} from 'vue'
import {onShow} from '@dcloudio/uni-app'
import BrandMark from '../../components/BrandMark.vue'
import AppIcon from '../../components/AppIcon.vue'
import {cloudSession,request,refreshSession,requireLogin} from '../../utils/cloud'
import {getCloudWork} from '../../utils/cloudWorks'
import {setPending} from '../../utils/appState'
const info=uni.getSystemInfoSync(),nav={statusBar:info.statusBarHeight||0,height:56,right:0}
// #ifdef MP-WEIXIN
const capsule=uni.getMenuButtonBoundingClientRect();nav.height=(capsule.top-nav.statusBar)*2+capsule.height;nav.right=info.windowWidth-capsule.left-28
// #endif
const summary=ref({}),error=ref(''),opening=ref(false)
watch(()=>cloudSession.user?.id,()=>{summary.value={};error.value='';opening.value=false})
async function load(){if(!cloudSession.user)return;error.value='';try{await refreshSession();summary.value=await request('/me/overview')}catch(e){error.value=e.message}}
onShow(load)
const formatDate=v=>new Date(v).toLocaleDateString('zh-CN')
const formatStock=v=>Number(v||0)>=10000?(Number(v)/10000).toFixed(1)+'万':(v||0)
function account(section='login'){uni.navigateTo({url:'/member/account/account?section='+section})}
function works(){uni.switchTab({url:'/pages/history/history'})}
function inventory(){if(requireLogin())uni.navigateTo({url:'/member/inventory/inventory'})}
function favorites(){if(requireLogin()){uni.setStorageSync('douwu_discovery_view','favorites');uni.switchTab({url:'/pages/templates/templates'})}}
function guide(){uni.navigateTo({url:'/member/guide/guide'})}
function privacy(){uni.navigateTo({url:'/pages/privacy/privacy'})}
async function continueWork(){if(opening.value||!summary.value.recent)return;opening.value=true;try{const item=await getCloudWork(summary.value.recent.id);setPending('',item.pattern,item.colorUsage,item.gridSize,{id:item.id,templateId:item.templateId,name:item.name,paletteName:item.paletteName,attribution:item.attribution});uni.navigateTo({url:'/pages/result/result'})}catch(e){uni.showToast({title:e.message,icon:'none'})}finally{opening.value=false}}
</script>
<style scoped>
.me-page{min-height:100vh;background:#f6f5f3}.me-nav>view{display:flex;align-items:center;gap:14rpx;margin:0 32rpx;font-size:34rpx;font-weight:650}.me-nav button{margin-left:auto;background:transparent;font-size:24rpx;color:#727272;padding:20rpx 0 20rpx 30rpx}.me-body{padding:16rpx 32rpx 40rpx}.identity{display:flex;align-items:center;gap:24rpx;padding:28rpx 0 36rpx}.avatar{width:112rpx;height:112rpx;display:flex;align-items:center;justify-content:center;border:8rpx solid #fff;background:#e6e2d9;border-radius:40rpx;color:#585858;font-size:48rpx;box-shadow:0 6rpx 20rpx #24232108}.identity-copy{flex:1;min-width:0}.identity-title{display:block;font-size:38rpx;font-weight:650}.muted{display:block;font-size:22rpx;color:#8e8e8e;line-height:1.6;margin-top:10rpx}.login{display:flex;align-items:center;justify-content:space-between;padding:26rpx;font-size:27rpx;margin-bottom:20rpx}.login>text{font-size:21rpx;font-weight:400;opacity:.7}.stats{display:flex;margin:4rpx 0 34rpx}.stats button{flex:1;background:transparent;color:#868686;font-size:22rpx;padding:12rpx;line-height:1.6}.stats button>text{display:block;font-size:38rpx;color:#242321;font-weight:650;margin-bottom:4rpx}.stats button+button{border-left:1rpx solid #e9e6df}.membership{padding:30rpx;border-radius:26rpx;background:linear-gradient(120deg,#242321,#565656);color:#ebe7df;position:relative;overflow:hidden}.membership::after{content:'';position:absolute;width:230rpx;height:230rpx;border:38rpx solid #f3df9c0a;transform:rotate(22deg);right:-55rpx;top:20rpx;border-radius:52rpx;pointer-events:none}.membership-top{display:flex;align-items:center;justify-content:space-between}.pro-logo{font-size:27rpx;font-weight:650;letter-spacing:2rpx}.pro-logo>text{font-size:17rpx;letter-spacing:1rpx;border:1rpx solid #d9ce99;border-radius:5rpx;padding:2rpx 6rpx;margin-left:6rpx;color:#eddfa6}.membership-top>text:last-child{font-size:19rpx;color:#cec7b8}.membership-title{display:block;font-size:35rpx;font-weight:600;margin-top:32rpx;color:#f3ebc9}.membership-desc{display:block;font-size:21rpx;margin-top:12rpx;opacity:.75}.membership-bottom{display:flex;align-items:center;justify-content:space-between;border-top:1rpx solid #ffffff20;padding-top:22rpx;margin-top:30rpx;font-size:21rpx}.member-action{background:#f1e6bb;color:#242321;padding:12rpx 18rpx;border-radius:12rpx}.recent{display:flex;align-items:center;gap:20rpx;background:#f1eee8;border-radius:20rpx;padding:24rpx;margin-top:22rpx}.recent>view:nth-child(2){flex:1;min-width:0}.recent-icon{background:#fff;width:72rpx;height:72rpx;border-radius:20rpx;display:flex;align-items:center;justify-content:center}.row-title{font-size:26rpx;font-weight:600}.ellipsis{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.group-label{display:block;color:#707070;font-size:23rpx;margin:36rpx 2rpx 20rpx;letter-spacing:2rpx}.tool-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12rpx}.tool-grid button{background:#fff;border:1rpx solid #ece9e2;padding:24rpx 6rpx;border-radius:20rpx;line-height:1.5;font-size:24rpx;color:#242321}.tool-grid .muted{font-size:18rpx;margin-top:7rpx}.tool-symbol{height:66rpx;display:flex;align-items:center;justify-content:center;font-size:48rpx;color:#626262;margin-bottom:8rpx}.menu-list{border:1rpx solid #e9e6df;border-radius:22rpx;overflow:hidden;background:#fff}.menu-list button{display:flex;align-items:center;gap:18rpx;font-size:25rpx;color:#242321;padding:29rpx 24rpx;background:transparent;line-height:1.6}.menu-list button+button{border-top:1rpx solid #f2f0eb}.menu-hint{margin-left:auto;font-size:19rpx;color:#989898}.me-footer{display:flex;align-items:center;justify-content:center;gap:10rpx;margin:42rpx 0 6rpx;font-size:19rpx;color:#a0a0a0}.retry{display:flex;align-items:center;font-size:22rpx;color:#a27651;margin-bottom:20rpx}.retry button{font-size:22rpx;color:#242321;background:transparent;margin-left:auto}

.me-nav>view { margin:0 36rpx; font-size:46rpx; font-weight:700; }.me-nav button { min-height:88rpx; font-size:26rpx; }
.me-body { padding:12rpx 36rpx 36rpx; }.identity { padding:22rpx 0 28rpx; }.avatar { border-radius:50%; width:104rpx; height:104rpx; background:#e9e6df; border:0; box-shadow:none; font-size:40rpx; }.identity-title { font-size:34rpx; }.identity-copy .muted { font-size:22rpx; }
.stats { background:#fff; border-radius:24rpx; padding:22rpx 0; margin:0 0 22rpx; }.stats button { font-size:22rpx; }.stats button>text { font-size:36rpx; }.stats button+button { border-left:0; }
.group-label { margin:28rpx 0 18rpx; letter-spacing:0; font-size:25rpx; color:#777777; }.tool-grid { gap:14rpx; }.tool-grid button { padding:22rpx 8rpx; border:0; border-radius:22rpx; font-size:24rpx; }.tool-grid .muted { display:none; }.tool-symbol { height:60rpx; margin-bottom:8rpx; }
.membership-compact { width:100%; margin-top:24rpx; border-radius:22rpx; background:#e8e6f2; padding:26rpx 22rpx; display:flex; align-items:center; gap:18rpx; color:#4b4964; text-align:left; line-height:1.4; }.pro-badge { background:#59566f; color:#fff; border-radius:12rpx; padding:15rpx 10rpx; font-size:20rpx; letter-spacing:1rpx; }.membership-compact>view:nth-child(2) { flex:1; min-width:0; }.membership-compact text { display:block; font-size:27rpx; font-weight:600; }.membership-compact text+text { font-size:20rpx; color:#848199; margin-top:8rpx; font-weight:400; }
.menu-list { border:0; border-radius:22rpx; }.menu-list button { padding:30rpx 22rpx; font-size:26rpx; min-height:104rpx; }.menu-hint { font-size:20rpx; }.me-footer { margin-top:32rpx; }.recent { border-radius:22rpx; background:#fff; }
</style>

<style scoped>
.me-nav{background:#242321;color:#fff}.me-nav button{color:#C4BDAF}.identity{background:#242321;margin:-12rpx -36rpx 0;padding:34rpx 36rpx 64rpx;color:#fff}.avatar{background:#FFD44D;color:#242321;border-radius:25rpx}.identity-title{color:#fff}.identity-copy .muted{color:#A6A198;font-size:22rpx}.stats{position:relative;margin-top:-26rpx;background:#fff;border-radius:26rpx;padding:28rpx 0;box-shadow:0 8rpx 24rpx #00000005}.stats button>text{color:#242321}.login{margin-top:24rpx;background:#FFD44D;color:#242321}.identity+button+.stats{margin-top:0}.membership-compact{background:#FFE8A0;color:#776025}.pro-badge{background:#242321;color:#FFD44D}.membership-compact text+text{color:#AF954E}.tool-symbol{color:#B69B52}.tool-grid button{background:#fff}.menu-list button{color:#242321}.menu-hint{color:#B3AA99}.group-label{color:#A69B86;font-size:23rpx}.me-footer{color:#B7AD99}.retry{margin-top:24rpx}
</style>
